window.__mean&&window.__mean(1,{"0":[[0,0,[["الْحَمْدُ","الثناء بالجميل على جهة التّفضيل.",2]]],[2,2,[["رَبِّ","السّيّد، والمالك، وزوج المرأة  والمصلح، والمربّي، والملك، والمعبود. ولا يستعمل معرّفا بأل إلا معه تعالى.",2]]],[3,3,[["الْعالَمِينَ","أصناف الخلق، كلّ صنف منهم عالم  والمشهور أنه جمع عالم، وقيل: اسم جمع.",2]]]],"2":[[2,2,[["الدِّينِ","الجزاء، ويأتي بمعنى الحساب، والطاعة، والعبادة، وما يتديّن به من الإسلام وغيره، والسّلطان  ولغير ذلك  .",2]]]],"3":[[1,1,[["نَعْبُدُ","لغة: التّذلّل، وتفسيرا: الطاعة مع الخضوع، قال ابن عيسى  : خضوع ليس فوقه خضوع.",2]]],[3,3,[["نَسْتَعِينُ","نطلب المعونة، وهي الزيادة على القوة بما يسهّل الوصول إلى البغية.",2]]]],"4":[[0,0,[["اهْدِنَا","أرشدنا  . وقيل: ثبّتنا على المنهاج الواضح. وقيل غير ذلك. والهداية: الدّلالة، وقال ابن عيسى: الدّلالة على طريق الحقّ.",2]]],[1,2,[["الصِّراطَ الْمُسْتَقِيمَ","الطّريق الواضح، وهو الإسلام   وقيل: القرآن، وقيل: محمد عليه الصلاة والسلام، وقيل غير ذلك  .",2]]]],"5":[[1,3,[["الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","الإنعام: النفع الذي يستحق به الشّكر، وأصله من النّعمة، وهي اللّين. والنّعم: الخفض والدّعة، وهو لين العيش ورفاهيّته.والمنعم عليهم: الأنبياء، أو الملائكة، أو المؤمنون، أو النّبيّ عليه الصلاة والسلام، أو قوم موسى وعيسى عليهما الصلاة والسلام قبل أن غيّروا نعم الله عليهم، أو المشار إليهم في سورة النّساء بقوله: فَأُولئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ  الآية، أقوال.",2]]]],"6":[[1,2,[["الْمَغْضُوبِ عَلَيْهِمْ","اليهود. والضَّالِّينَ [7] : النصارى  .وقيل: المغضوب عليهم: المشركون. والضالّون: المنافقون. وقيل:المغضوب عليهم: اليهود والنصارى، والضالّون: سائر الكفار، وقيل غير ذلك  .الغضب، لغة: الشّدّة، وحقيقته: غليان دم القلب حبّا في التّشفي. وغضب الله تعالى: إرادة الانتقام، أو معاملة الغاضب لمن غضب عليه، أو سبّ الله أعداءه في كتابه، أقوال. ولَا صلة.والضّلال: نقيض الهدى، وأصله من الضّياع.آمين، بتخفيف الميم، يمد في اللغة الفصحى، قال الشاعر:آمين آمين لا أرضى بواحدة ... حتى أبلّغها ألفين آمينا يمدّ ويقصر، تفسيره: اللهم استجب، فهو اسم فعل مبني على الفتح، مثل:كيف  وأين.ويقال: هو اسم من أسماء الله تعالى.وفيه تخفيف الميم مع المدّ والإمالة، وتشديد الميم مع المدّ والقصر.",2]]]],"7":[[0,0,[["الم","وسائر حروف الهجاء في أوائل السّور: كان بعض المفسّرين يجعلها أسماء للسّور، تعرف كلّ سورة بما افتتحت به  . وبعضهم يجعلها أقساما أقسم الله- عز وجل- بها لشرفها وفضلها، ولأنها مبادئ كتبه المنزّلة ومباني أسمائه الحسنى وصفاته العليا.وبعضهم يجعلها حروفا مأخوذة من صفات الله تعالى، كقول ابن عبّاس  في كهيعص  إن الكاف من كاف، والهاء من هاد، والياء من حكيم، والعين من عليم، والصاد من صادق   وقيل غير ذلك.",2]]],[4,4,[["ريب","الشك",1]]],[6,6,[["هُدىً","رشد  وهو كلّ ما يهتدى به.",2]]],[7,7,[["لِلْمُتَّقِينَ","المتّقي: من يقي نفسه عن تعاطي ما يعاقب عليه من فعل أو ترك. وأصل الاتّقاء: الحجز، وذكرت هذه في القرآن في مائتين وستة وثلاثين موضعا.",2]]]],"8":[[0,2,[["الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ","يصدّقون بأخبار الله- تعالى- عن الجنّة والنار والقيامة والحساب، وأشباه ذلك  .والمؤمن: المصدّق، والله- تعالى- مؤمن، أي مصدّق ما وعد. ويكون أيضامن الأمان، أي لا يأمن إلا من أمنه  .والغيب: ما غاب عن الحاسّة مما يعلم بالأدلة.",2]]],[3,4,[["وَيُقِيمُونَ الصَّلاةَ","إقامتها: أن يؤتى بها بحقوقها، كما فرضها الله تعالى. يقال: قام بالأمر وأقام الأمر، إذا جاء به معطى حقوقه [زه] والصلاة هنا ذات الرّكوع والسّجود، وتأتي على أربعة أوجه أخر: الدّعاء، والتّرحّم، والاستغفار، والدّين  .",2]]],[5,7,[["وَمِمَّا رَزَقْناهُمْ يُنْفِقُونَ","أي يزكّون ويتصدّقون  .",2]]]],"9":[[2,4,[["بِما أُنْزِلَ إِلَيْكَ","أصل الإنزال التّصيير إلى جهة السّفل، وكذلك التّنزيل.",2]]],[5,8,[["وَما أُنْزِلَ مِنْ قَبْلِكَ","قبل: لما مضى من الزّمان نقيض «بعد» .",2]]],[10,11,[["هُمْ يُوقِنُونَ","الإيقان: علم [حاصل]  بالاستدلال.",2]]]],"10":[[7,7,[["الم","كان جماعه من العلماء يرون هذا من المتشابه الذى انفرد الله تعالى بعلمه وفسره اخرون فقالوا هى حروف من أسماء الله تعالى",1]]]],"11":[[2,2,[["كَفَرُوا","ستروا وجحدوا نعم الله.",2]]],[3,4,[["سَواءٌ عَلَيْهِمْ","مستو عندهم.",2]]],[5,5,[["أَأَنْذَرْتَهُمْ","أأعلمتهم بما تحذّرهم منه، ولا يكون المعلم منذرا حتى يحذّر بإعلامه، فكلّ منذر معلم وليس كلّ معلم منذرا  والهمزة للتّسوية.",2]]]],"12":[[0,3,[["خَتَمَ اللَّهُ عَلى قُلُوبِهِمْ","أي طبع عليها   ووسمها بسمةالكفّار. والقلب: الفؤاد، سمّي قلبا لتقلّبه بالخواطر والعزوم. وهو محلّ العزم والفكر والعلم والقصد.",2]]],[4,5,[["وَعَلى سَمْعِهِمْ","السّمع والسّماع مصدران لسمع. والسّمع: الأذن أيضا.",2]]],[6,7,[["وَعَلى أَبْصارِهِمْ","جمع بصر، وهي حاسّة يدرك بها المبصر، ويستعمل للمصدر أيضا.",2]]],[8,8,[["غِشاوَةٌ","أي غطاء  والغشاوة: الغطاء السابل، أي جعل قلوبهم بحيث لا تفهم، وآذانهم بحيث لا تسمع بالمسموع، وأبصارهم بحيث لا تنتفع بالمرئي.",2]]],[9,11,[["وَلَهُمْ عَذابٌ عَظِيمٌ","العذاب: إيصال الألم حالا بعد حال. وقيل:أصله استمرار للشيء. والعظيم: الدائم الذي لا ينقطع. والعظم في الأصل: الزّيادة على المقدار، ثم ينقسم إلى عظم الشّأن وعظم الأجسام.",2]]]],"13":[[0,3,[["وَمِنَ النَّاسِ مَنْ يَقُولُ","الناس والإنس: البشر، واشتقاقه من النّوس وهو الحركة، أو من الإنس، أو من النّسيان، أقوال.والقول والكلام يطلقان لغة على اللّساني والنّفساني بالاشتراك. أو حقيقة في أحدهما مجاز في الآخر، مذاهب.",2]]],[6,7,[["وَبِالْيَوْمِ الْآخِرِ","سمّي بذلك لأنه بعد أيام الدنيا، وقيل: لأنه آخر يوم يلي  ليلة.",2]]]],"14":[[0,1,[["يُخادِعُونَ اللَّهَ","بمعنى يخدعون، أي يظهرون خلاف ما في قلوبهم، وقيل: يظهرون الإيمان بالله- تعالى- ورسوله- صلّى الله عليه وسلّم- ويضمرون خلاف ما يظهرون. فالخداع منهم يقع بالاحتيال والمكر، ومن الله- عز وجل- بأن يظهر لهم من الإحسان ويعجّل لهم من النّعيم في الدنيا خلاف ما يغيّب عنهم ويستر من عذابالآخرة لهم [جزاء لفعلهم]  ، فجمع الفعلان لمشابهتهما من هذه الجهة. وقيل:معنى الخدع في كلامهم: الفساد، ومنه قول الشاعر:طيّب  الرّيق إذا الرّيق خدع أي فسد.فمعنى يُخادِعُونَ اللَّهَ: يفسدون ما يظهرون من الإيمان بما يضمرون من الكفر، كما يفسد الله عليهم نعيمهم في الدنيا بما يصيرون إليه من عذاب الآخرة.",2]]],[8,9,[["وَما يَشْعُرُونَ","أي ما يعلمون ذلك ويفطنون له  .",2]]]],"15":[[2,2,[["مرض","الشك",1]]],[3,3,[["فَزادَهُمُ","الزّيادة: الإلحاق بالمقدار ما ليس منه، والنّقصان:الإخراج عن المقدار ما هو منه، والتّمام: البلوغ حد المقدار من غير زيادة ولا نقصان.",2]]],[8,8,[["أَلِيمٌ","مؤلم، أي موجع  وقيل: الألم يعمّ كلّ أذى صغر أو كبر.",2]]],[11,11,[["يَكْذِبُونَ","التّكذيب: نسبة المخبر إلى الكذب وهو نقيض الصّدق، أي الإخبار عن الشيء على خلاف ما هو به.",2]]]],"16":[[3,6,[["لا تُفْسِدُوا فِي الْأَرْضِ","الإفساد: التغيير عن استقامة الحال، والفساد: التغيّر عنها، تقول: فسدت التفاحة، إذا عفنت.والأرض: هي الغبراء التي عليها مستقر الخلق.",2]]],[10,10,[["مُصْلِحُونَ","الإصلاح: التّغيير إلى استقامة الحال.",2]]]],"18":[[11,11,[["السُّفَهاءُ","أي الجهّال. والسّفه: الجهل، بلغة كنانة  ، ثم يكون لكلّ شيء، يقال للكافر سفيه لقوله: سَيَقُولُ السُّفَهاءُ مِنَ النَّاسِ  يعني اليهود»، وللجاهل سفيه لقوله: فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً أَوْ ضَعِيفاً  ، قال مجاهد  هما: السّفيه الجاهل، والضّعيف الأحمق  و [يقال] «7» للنّساء والصّبيان سفهاء لجهلهم لقوله: وَلا تُؤْتُوا السُّفَهاءَ أَمْوالَكُمُ «8» يعني الصبيان والنساء «9» [زه] يعني غير الرّشيدات منهن. وقيل: السّفه في اللغة: الخفّة. وثوب سفيه أي خفيف بال، وهو أيضا: الذي يدل على خفّة الحلم.",2]]]],"19":[[0,1,[["وَإِذا لَقُوا","إذا: ظرف مستقبل. واللّقاء: الاجتماع مع الشيء على طريق المقاربة.",2]]],[8,9,[["إلى شياطينهم","رؤوسهم فى الكفر",1]]],[15,15,[["مُسْتَهْزِؤُنَ","ساخرون   .",2]]]],"20":[[1,2,[["يستهزئ بهم","أى يجازيهم على استهزائهم",1]]],[3,3,[["ويمدهم","أى يملي لهم",1]]],[6,6,[["يعمهون","يتحيرون",1]]]],"21":[[2,3,[["اشتروا الضلالة","استبدلوا الكفر بالايمان",1]]],[5,7,[["فَما رَبِحَتْ تِجارَتُهُمْ","الرّبح: الزّيادة على رأس المال والتجارة، قال الزمخشريّ  : هي صناعة التاجر، وهو الذي يبيع ويشتري للرّبح. وناقة تاجرة:كأنها من حسنها وسمنها تبيع نفسها  انتهى.وقضية  كلامه أن التّجارة والبيع والشّراء للربح. ورد بأنها للشراء للاسترباح بدليل لا تُلْهِيهِمْ تِجارَةٌ وَلا بَيْعٌ «7» والعطف يدل على المغايرة وبأنه لو حلف لايتّجر فاشترى للربح حنث، ومعنى قولهم: ناقة تاجرة، أنها تحمل المشتري على شرائها، لا أنها تبيع نفسها.",2]]]],"22":[[0,4,[["مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ ناراً","أي أوقد  مثل استجاب بمعنى أجاب، وقيل: هو على بابه وهو استدعاء الإيقاد. والمثل في أصل كلامهم بمعنى المثل وهو النّظير. ويقال: مثل ومثل ومثيل كشبه وشبه وشبيه، ثم قيل للقول السائر: المثل مضربه بمورده مثل، والمراد به هنا الصفة. والنار: جوهر لطيف مضيء حار محرق، واشتقاقها من نار ينور إذا نفر لأن فيها حركة واضطرابا.",2]]],[5,8,[["فَلَمَّا أَضاءَتْ ما حَوْلَهُ","لمّا: كلمة تدل على وجود  شيء لوجود غيره.وأضاءت وضاءت لغتان بمعنى.ويجوز في «ما» أن تكون موصولة، وأن تكون نكرة موصوفة، وأن تكون صلة.وحول الشيء: ما دار من جوانبه. وتأليفه للدوران والإطافة.",2]]],[9,9,[["ذَهَبَ","الذّهاب بالمرور أو الزّوال أو الإبطال، تفسيرات.والإذهاب: الحمل عليه، وكذلك الذّهاب به.",2]]],[11,11,[["بِنُورِهِمْ","النور: الضوء  النّور: نقيض الظّلمة، واشتقاقه من النّار.",2]]],[12,12,[["وَتَرَكَهُمْ","يجوز أن يكون ترك بمعنى صيّر، وأن يكون بمعنى طرح وخلّى.",2]]],[13,14,[["فِي ظُلُماتٍ","جمع ظلمة، وهي مرض ينافي النّور. وقيل:عدم النّور وكذلك الظّلام، واشتقاقها من قولهم: ما ظلمك أن تفعل كذا، أي ما منعك وما شغلك لأنها تسد البصر وتمنع الرّؤية.",2]]]],"23":[[0,0,[["صُمٌّ","جمع أصمّ، والصّمم في الأذن يمنع من السّمع، وأصله الصّلابة، وقيل: أصله السّدّ.",2]]],[1,1,[["بُكْمٌ","خرس  والبكم: آفة في اللّسان مانعة من الكلام.والأبكم: الذي يولد أخرس. وقيل: هو المسلوب الفؤاد الذي لا يعي شيئا ولا يفهم.",2]]],[2,2,[["عُمْيٌ","جمع أعمى، والعمى: آفة في العينين مانعة من إدراك المبصر. والمعنى صمّ عن استماع الحقّ، بكم عن التّكلّم به، عمي عن الإبصار له.",2]]]],"24":[[1,1,[["كصيب","المطر",1]]],[6,7,[["وَرَعْدٌ وَبَرْقٌ","يروى عن النبي- صلّى الله عليه وسلّم- أنه قال: «إنّ الله- عز وجلّ- ينشئ السحاب فينطق أحسن النّطق ويضحك أحسن الضّحك، فمنطقه الرّعد وضحكه البرق»  . وقال ابن عباس: «الرّعد ملك اسمه الرّعد، وهو الذي تسمعون صوته، والبرق: سوط من نور  يزجر به الملك السحاب» . وقال أهل اللّغة: الرّعد: صوت السحاب، والبرق: نور وضياء يصحبان السحاب  وفي صحّة الحديث نظر. وللمفسرين في مسمّى الرّعد أقوال بلّغتها سبعة، وفي مسمّى البرق بلّغتها ستة، وقد بينتها في موضع آخر، قال أبو حيّان  : «والذي يفهم من اللغة أنّ الرّعد عبارة عن الصّوت المزعج المسموع من جهة السماء، وأن البرق هو  الجرم اللّطيف النّوراني الذي يشاهد ولا يثبت»  .",2]]],[8,11,[["يَجْعَلُونَ أَصابِعَهُمْ فِي آذانِهِمْ","أي يلقونها فيها. وفي واحد الأصابع عشر لغات: بتثليث الهمزة والباء والعاشرة أصبوع  ، بضمّ الهمزة والباء.",2]]],[12,13,[["مِنَ الصَّواعِقِ","هي جمع صاعقة، وهي صوت. والصاعقة أيضا: كل عذاب مهلك، والصاعقة أيضا: الموت بلغة عمان  . وقال الخليل  :هي الواقعة الشديدة من صوت الرعد، يكون معها أحيانا قطعة نار تحرق ما أتت عليه  .وقال أبو زيد  : هي نار تسقط من السماء في رعد شديد. وبين التفسيرين فروق بيّنتها في موضع.وقال الزّمخشريّ: الشقة المنقضّة مع قصفة الريح الرعد  .",2]]],[14,15,[["حَذَرَ الْمَوْتِ","الجزع والحذر والفرق والفزع نظائر. والموت يكون مصدرا كمات يموت كقال يقول، أو كمات يمات  كخاف يخاف. ويكون اسما، وهو يقابل الحياة تقابل الملكة والعدم عند المعتزلة «7» ، فهو زوال الحياة، وتقابل الضّدّين عند الأشعرية «8» فقيل: هو عرض يعقب الحياة. وقيل: عرض لا يصح معه إحساس يعقب الحياة.",2]]],[17,17,[["مُحِيطٌ","الزّجّاجيّ «9» : هو من أحاط بالشيء، إذا استولى عليهوضمّ جميع أقطاره ونواحيه حتى لا يمكنه التخلّص منه ولا فوته. وقيل: الإحاطة:حصر الشيء بالمنع له من كل جهة، قال الزجاجيّ: حقيقة الإحاطة بالشيء: ضمّ أقطاره ونواحيه ونظيره وسطا كإحاطة البيت بمن فيه والأوعية بما يحلها. وأصل جميع ذلك راجع إلى معنى الحائط لإحاطته بما يدور عليه، تم اتّسع فيه واستعمل في القدرة والعلم والإهلاك لتقارب المعاني. وقال الكواشي  : وأصل الإحاطة الإحداق بالشيء من جميع جهاته، ومنه الحائط. وقال بعضهم: الإحاطة بالشيء والإحداق به والإطافة به نظائر في اللّغة.",2]]]],"25":[[0,0,[["يَكادُ","يهم ولم يفعل، يقال: كاد يفعل، ولا يقال: كاد أن يفعل   وأجاز ابن مالك وغيره أن يقال في السّعة: كاد أن يفعل»، ومنه قول عمر  : «ما كدت أصلّي العصر حتى كادت الشمس أن تغرب» .",2]]],[1,1,[["وَلَوْ","حرف يقتضي في الماضي امتناع ما يليه واستلزامه لتاليه.",2]]],[2,2,[["يَخْطَفُ","الخطف: أخذ الشيء بسرعة.",2]]],[7,7,[["شاءَ","أراد كل شيء. الشيء مصدر شاء، فإذا وصف به الله- تعالى- فمعناه شاء  ، وإذا وصف به غيره فمعناه المشيء. والغالب خروجه عن المصدرية واستعماله اسما غير ملاحظ فيه اشتقاق، كما يقال: ما عندي شيء.",2]]],[10,10,[["أَظْلَمَ","يجوز أن تكون همزته للصيرورة، أي صار الموضع مظلما، أو ذا ظلام، وأن تكون للدخول في الشيء كالذي في أنجد وأصاف، إذا  دخل نجدا أو في الصّيف.",2]]],[12,12,[["قامُوا","وقفوا وثبتوا في مكانهم.",2]]],[24,24,[["قَدِيرٌ","هو أبلغ من قادر، وكلاهما من القدرة وهو القوّة والاستطاعة بمعنى.",2]]]],"26":[[0,0,[["يا أَيُّهَا","يا: حرف نداء، وقيل: اسم فعل هو: أنادي، ولم يقع النّداء في القرآن مع كثرته إلا بها، وينادى بها القريب وغيره. أيّ: وصلة لنداء ما فيه أل أو مناداه، عبارتان. ها: حرف تنبيه.",2]]],[5,5,[["خَلَقَكُمْ","الخلق: الإبداع بلا مثال، وأصله التّقدير. وخلقت الأديم: قدّرته. وقال قطرب  : هو الإيجاد على تقدير وترتيب. والخلق والإيجاد والإحداث والإبداع والاختراع والإنشاء متقاربة.",2]]],[8,8,[["قَبْلِكُمْ","قبل: ظرف زمان، وأصله وصف ناب عن موصوفه لزوما، فإذا قلت: قمت قبل زيد، فالتقدير: قمت زمانا قبل زمان قيام زيد، فحذف هذا كله وناب عنه: قبل زيد.",2]]],[9,9,[["لَعَلَّكُمْ","لعلّ: حرف توقع يكون للترجّي في المحبوب، وللإشفاق في المكروه، ولا يستعمل إلا في الممكن.",2]]]],"27":[[4,4,[["فِراشاً","الفراش: المهاد، أي ذلّلها لكم، ولم يجعلها حزنة غليظة لا يمكن الاستقرار عليها  وقيل: الفراش: الوطاء الذي يقعد عليه، وينام ويتقلب عليه.",2]]],[5,5,[["والسَّماءِ","في اللغة: كل ما علاك فأظلّك، وهل المراد ذات البروج أو السّحاب، قولان.",2]]],[6,6,[["بِناءً","هو مصدر، وقد يراد به المفعول من بيت أو قبّة أو خباء أوظراف. وأبنية العرب: أخبيتهم.",2]]],[7,8,[["والماء","معروف، وعرّفه بعضهم بأنه جوهر شفّاف لا لون له، وما يظهر فيه من اللون لون ظرفه أو ما يقابله. ووصفه الغزالي  في «الوسيط» بالتركيب  ونوقش في ذلك بأنه بسيط ويقصد للرّي، وبعضهم بأنه جوهر سيّال به قوام الحيوان.",2]]],[13,14,[["مِنَ الثَّمَراتِ","الثّمرة: ما تخرجه الشجرة من مطعوم أو مشموم.",2]]],[20,20,[["أندادا","الأمثال الأشكال وهى الاصنام",1]]]],"28":[[7,7,[["دُونِ","ظرف مكان ملازم للظرفية الحقيقية أو المجازية ولا يتصرف فيه بغير «من» .",2],["عَبْدِنا","العبد لغة: المملوك الذّكر من جنس الإنسان، وقيل: والأنثى أيضا.",2]]],[8,8,[["فَأْتُوا","الإتيان: المجيء.",2]]],[9,9,[["بِسُورَةٍ","السّورة غير مهموزة: منزلة يرتفع القارئ منها إلىمنزلة أخرى إلى أن يستكمل القرآن كسور البناء. وبالهمزة: قطعة  من القرآن على حدة، من قولهم: أسأرت من كذا، أي: أبقيت وأفضلت منه فضلة  وقيل:الدّرجة الرفيعة، وسمّيت بها سور القرآن لأن قارئها يشرف بقراءتها على من لم تكن عنده كسور البناء. وقيل: لتمامها وكمالها، ومنه قيل للناقة التّامة: سورة.أو لأنها قطعة من القرآن، من أسأرت والسؤر فأصلها الهمز وخفّفت، قاله أبو عبيدة، والهمز فيها لغة.",2]]],[10,11,[["مِنْ مِثْلِهِ","المماثلة تقع بأدنى مشابهة، وقد ذكر سيبويه  أن:مررت برجل مثلك، يحتمل وجوها ثلاثة  .",2]]],[12,13,[["وادعوا شهداءكم","اى استعينوا بالهتكم وسموا شهداء لانهم يشهدونهم ويحضرونهم",1]]],[19,19,[["صادِقِينَ","الصّدق مقابله الكذب، وهو مقابلة الخبر للمخبر عنه ولا واسطة بينهما عند الجمهور.",2]]]],"29":[[3,3,[["لَنْ","حرف نفي في المستقبل.",2]]],[5,5,[["فَاتَّقُوا","احذروا.",2]]],[8,8,[["وَقُودُهَا","الوقود: اسم لما يوقد، وبالضّم: المصدر، وجاءفي المصدر الفتح أيضا، حكاه سيبويه والأخفش  ، وهو أحد المصادر التي جاءت على فعول بقلّة  . قال ابن عصفور  : لم يحفظ منها سوى هذا والوضوء والطّهور والولوع والقبول.",2]]],[10,10,[["الْحِجارَةُ","جمع الحجر، والتاء فيه لتأكيد تأنيث الجمع كالفحولة.",2]]],[11,11,[["أُعِدَّتْ","ادّخرت وهيّئت.",2]]]],"30":[[0,0,[["بَشِّرِ","أي أخبر خبرا يظهر أثره على البشرة، وهو ظاهر الجلد.والبشارة: أوّل خبر يرد على الإنسان من خير أو شرّ وأكثر استعماله في الخير، واستعماله في الشر قيل: مجاز، وقيل: حقيقة، فتكون مشتركا.",2]]],[3,4,[["وَعَمِلُوا الصَّالِحاتِ","العمل: إيجاد الشيء بعد أن لم يكن.والصّلاح: الفعل المستقيم، وهو مقابل الفساد.",2]]],[7,7,[["جَنَّاتٍ","جمع جنّة، وهي في اللغة البستان فيه نخل وشجر، وقيل: البستان الذي سترت  أشجاره أرضه. وكل شيء ستر شيئا فقد أجنّه، ومن ذلك الجنّة والجنّة والجن والمجن والجنين، فإن كان فيه كرم فهي فردوس.والمراد هنا دار الله في الآخرة.",2]]],[8,11,[["تجري من تحتها الأنهار","اى من تحت شجرها",1]]],[12,17,[["كُلَّما رُزِقُوا مِنْها مِنْ ثَمَرَةٍ رِزْقاً","أي كلما أطعموا فاكهة منها.",2]]],[19,23,[["هذا الذي رزقنا من قبل","اى رزق الغداة كرزق العشى فهو متشابه المنظر مختلف الطعم",1]]],[26,26,[["مُتَشابِهاً","يشبه بعضه بعضا في الجودة والحسن، ويقال: يشبهبعضه بعضا في الصّورة ويختلف في الطّعم  والتّشابه: تفاعل من الشّبه، والشّبه:المثل فيكون معناه التماثل.",2]]],[29,29,[["أَزْواجٌ","جمع زوج، وهو الواحد الذي يكون معه آخر، واثنان زوجان. ويقال للرجل زوج ولامرأته أيضا زوج، وزوجة أقلّ.",2]]],[30,30,[["مطهرة","اى نقيه من الاذى",1]]],[33,33,[["خالِدُونَ","باقون بقاء لا آخر له، وبه سمّيت الجنّة دار الخلد وكذلك النار  والخلود: المكث في الحياة أو الملك أو المكان مدة طويلة لا انتهاء لها. وهل يطلق على المدة الطويلة التي لها انتهاء بطريق الحقيقة أو المجاز؟ قولان.",2]]]],"31":[[2,3,[["لا يستحيي","لا يترك",1]]],[6,6,[["وما","زائدة",1]]],[8,8,[["بَعُوضَةً","هي واحد البعوض، وهي طائر صغير جدّا معروف، وهو في الأصل صفة على فعول فغلبت، أو اشتقاقه من البعض بمعنى القطع.",2]]],[9,10,[["فَما فَوْقَها","قيل: في الكبر، وقيل: في الصغر. وقال ابن قتيبة  : فوق من الأضداد يطلق على الأكثر والأقل.",2]]],[16,16,[["الْحَقُّ","الثابت الذي لا يسوغ إنكاره. والباطل مقابله وهو المضمحلّ الزائل.",2]]],[24,24,[["أَرادَ","الإرادة نقيضة الكراهة، مصدر أردت الشيء: طلبته. وقيل:الإرادة: المشيئة. والمشهور ترادفهما، فهي صفة مخصّصة لأحد طرفي الممكن بما هو جائز عليه من وجود أو عدم أو هيئة دون هيئة أو حالة دون حالة أو زمان دون زمان، وجمع ما يمكن أن يتصف به الممكن بدلا من خلافه أو ضدّه أو نقيضه أو مثله، غير أنها في الشاهد لا يجب لها حصول مرادها، وفي حق الله- تعالي- يجب لها ذلك لأنها في الشاهد عرض مخلوق مصرّف بالقدرة الإلهية، والمشيئة الربّانية هي مرادها. وفي حق الله- تعالى- معنى ليس بعرض واجب الوجود متعلّقة لذاتها أزليّة أبديّة واجبة النّفوذ بما تعلّقت به.",2]]],[30,30,[["كَثِيراً","هو ضد القليل.",2]]],[38,38,[["الْفاسِقِينَ","الخارجين عن أمر الله عز وجل، وقوله: فَفَسَقَ عَنْ أَمْرِ رَبِّهِ  أي خرج عنه. وكلّ خارج عن أمر الله فهو فاسق. فأعظم الفسق:الشّرك بالله، ثم ما أدّى إلى معاصيه  ، وحكي عن العرب: فسقت الرّطبة، إذا خرجت من قشرها  .وقيل: الفاسق شرعا: الخارج عن الحقّ، وجاء في مضارعه الضّمّ والكسر، قال ابن الأعرابيّ  : «لم يسمع قطّ في كلام الجاهلية ولا في شعرهم فاسق، قال:وهذا عجيب وهو كلام عربيّ»  .قلت: قال القرطبي: قد ذكر ابن الأنباريّ  في «الزاهر» لما تكلّم علىمعنى الفسق قول الشاعر:يهوين في نجد وغورا غائرا ... فواسقا عن قصدهم جوائرا",2]]]],"32":[[1,6,[["يَنْقُضُونَ عَهْدَ اللَّهِ مِنْ بَعْدِ مِيثاقِهِ","الميثاق: العهد موثّق من الوثيقة  والنّقض: فكّ تركيب الشيء وردّه إلى ما كان عليه أوّلا، فنقض البناء:هدمه، ونقض المبرم: حلّه. والعهد: الموثوق، وعهد إليه في كذا: وصّاه به ووثقه عليه، والعهد في أبيات العرب له ستة محامل: الوصيّة، والضّمان، والأمر، والالتقاء، والرؤية، والنّزل.  وأما الميثاق فالعهد المؤكد باليمين، والميثاق:الوثيقة، كالميعاد بمعنى الوعد والميلاد بمعنى الولادة.",2]]],[7,7,[["يَقْطَعُونَ","القطع: فصل الشيء عن الشيء بحيث يمكن أن يكون بينهما حاجز غيرهما.",2]]],[19,19,[["الْخاسِرُونَ","المغبونون لاستبدالهم النّقض بالوفاء والقطع بالوصل والفساد بالصلاح، قال العزيزي  : خسروا أنفسهم: غبنوها، انتهى.وقيل: الخسار: النقصان أو الهلاك.",2]]]],"33":[[3,4,[["وكنتم أمواتا","اى نطفا",1]]]],"34":[[8,11,[["ثم استوى إلى السماء","اى عمد الى خلقها ولفظها لفظ الواحد والمعنى معنى الجمع",1]]],[12,12,[["فَسَوَّاهُنَّ","أي جعلهن لا تفاوت فيهن. والتّسوية: التقويم والتعديل.",2]]]],"35":[[0,0,[["إِذْ","وقت ماض [زه] زعم أبو عبيدة وابن قتيبة  أنّ إذ هنا صلة، وبعضهم أنها بمعنى قد، وقيل غير ذلك.",2]]],[8,8,[["خَلِيفَةً","الخليفة: هو الذي قائم مقام غيره في الأمر الذي جعل إليه.",2]]],[12,14,[["من يفسد فيها","قال ابن مسعود علموا ذلك بتوفيق من الله تعالى وقال ابن عباس قاسو على حال من سلف",1]]],[15,16,[["وَيَسْفِكُ الدِّماءَ","يصبّها   السّفك: الصّبّ والإراقة ولا يستعمل إلا في الدم. ويقال سفك وأسفك وسفّك بمعنى، وفي مضارع المجرّد الكسر والضم.",2]]],[18,19,[["نُسَبِّحُ بِحَمْدِكَ","نصلّي ونحمدك. والتّسبيح: تنزيه الله وتبرئته عن السّوء، ولا يستعمل إلا لله تعالى.",2]]],[20,20,[["وَنُقَدِّسُ","ونطهّر [زه] والتّقديس: التّطهير، ومنه بيت المقدس والأرض المقدّسة. وقال الزّمخشريّ هو من قدّس في الأرض إذا ذهب فيها وأبعد  .",2]]]],"36":[[5,5,[["عَرَضَهُمْ","عرض الشيء: إظهاره حتى تعرف جهته.",2]]],[9,9,[["أَنْبِئُونِي","الإنباء: الإخبار.",2]]]],"37":[[1,1,[["سُبْحانَكَ","تنزيه وتبرئ»للرّب جلّ وعزّ  وسبحان:علم على التّسبيح.",2]]],[11,11,[["الْحَكِيمُ","فعيل بمعنى مفعل، من أحكم الشيء: أتقنه ومنعه من الخروج عما يريده.",2]]]],"38":[[18,18,[["تُبْدُونَ","تظهرون.",2]]],[21,21,[["تَكْتُمُونَ","تخفون.",2]]]],"39":[[1,2,[["قُلْنا لِلْمَلائِكَةِ","مذهب العرب إذا أخبر الرئيس منها عن نفسه قال: فعلنا وصنعنا لعلمه بأن أتباعه يفعلون بأمره كفعله ويجرون على مثل أمره، ثم كثر الاستعمال حتى صار الرّجل من السّوق يقول: فعلنا وصنعنا، والأصل ما ذكرت  وحكى الحريريّ  خلافا في علّة نون الجمع في كلام الله تعالى، فقيل:للعظمة وليس لمخلوق أن ينازعه فيها، فعلى هذا يكره استعمال الملوك لها في قولهم: فعلنا كذا. وقيل: لما كانت تصاريف أقضيته تعالى تجري على أيدي خلقهفنزلت أفعالهم منزلة فعله، فلذلك ورد الكلام موارد الجمع. فعلى هذا يجوز أن يستعمل النّون من لم يباشر الفعل [أي]  العمل بنفسه.",2]]],[3,3,[["اسْجُدُوا","السجود: التذلل والخضوع، وقال ابن السّكّيت  :هو الميل. وقال بعضهم: سجد: وضع جبهته بالأرض. وأسجد: ميّل رأسه وانحنى.",2]]],[7,7,[["أَبى","امتنع.",2],["إِبْلِيسَ","إفعيل من أبلس أي يئس، ويقال: هو اسم أعجميّ فلذلك لا ينصرف  للعجمة والعلميّة، وهذا هو المشهور واعتذر من قال بالاشتقاق فيه عن منع الصّرف بأنه لا نظير له في الأسماء، وردّ بإغريض وإزميل وإخريط وإجفيل وإعليط وإصليت وإحليل وإكليل وإحريض  .وقيل: شبّه بالأسماء الأعجمية فامتنع الصّرف للعلميّة وشبه العجمة. وشبه العجمة هو أنه وإن كان مشتقّا من الإبلاس فإنه لم يسمّ به أحد من العرب، فصار خاصّا بمن أطلقه الله عليه، وهو علم مرتجل.",2]]],[9,9,[["وَاسْتَكْبَرَ","تكبّر.",2]]]],"40":[[8,8,[["رَغَداً","واسعا بلا عناء [زه] وهو الخصب بلغة طيّئ  .",2]]],[9,9,[["حَيْثُ","ظرف مكان مبهم لازم الظّرفية.",2]]],[11,12,[["وَلا تَقْرَبا","هل النّهي للتّنزيه أو للتّحريم؟ قولان للمفسّرين حكاهما الإمام فخر الدين  ، ورجّح الأوّل لكونه أليق بمنصب نبوة آدم صلى الله عليه وسلم  .",2]]],[14,14,[["الشجرة","السنبله وقيل الكرم",1]]],[17,17,[["الظَّالِمِينَ","الظّلم: وضع الشّيء في غير موضعه، ومنه قولهم:«من أشبه أباه فما ظلم» أي فما وضع الشيء في غير موضعه  . هذا أصله ثم يطلق على الشّرك وعلى الجحد وعلى النّقص.والمظلومة: الأرض التي لم تمطر، ومعناه راجع إلى النّقص.",2]]]],"41":[[0,0,[["فَأَزَلَّهُمَا","أي استزلّهما، يقال: أزللته فزلّ، وأزالهما  :نحّاهما، يقال: أزلته فزال  قوله: أي استزلهما، يعني أنه من باب ورود أفعل بمعنى استفعل، وإلا فمادّتهما واحدة ومن جهل أحدهما جهل الآخر. وأزلّ وأزال من مادّتين مختلفتين لأن «أزلّ» من المضاعف، وهو من الزّلل. والزّلل: عثور القدم. ويقال: زلّت قدمه وزلّت به. والزّلل في الرّأي والنّظر مجاز. و «أزال» من الأجوف وهو من الزّوال، وأصله التّنحية. والهمزة في كلا الفعلين للتّعدية، وأفاد أن «أزلّ» و «أزال» مطاوعان، وأن مطاوع «أزلّ» «زال» ومطاوع «أزال» «زال» . ويقال: زال يزول، وزال يزال ويزيل والمعاني مختلفة.والأول: تامّ قاصر ومعناه الانتقال ومنه: إِنَّ اللَّهَ يُمْسِكُ السَّماواتِ وَالْأَرْضَ أَنْ تَزُولا  .والثاني: ناقص، ومعناه منفيّ، ولذلك إذا دخل عليه النّافي كان معناه الإثبات، نحو: ما زال زيد عالما.والثالث: تامّ متعدّ، يقال: زل ضأنك من معزك زيلا، أي ميّز.",2]]],[2,2,[["عَنْها","في مرجع الضّمير أقوال: الجنّة أو الشجرة أو الطاعة أو السماء. وقيل غير ذلك.",2]]],[8,8,[["اهْبِطُوا","الهبوط: الانحطاط من علوّ إلى سفل  ويقال:علوّ وسفل بالضم والكسر جميعا. اهْبِطُوا مِصْراً  : أنزلوها، وفي عين مضارعه الكسر والضّمّ.والهبوط بالفتح: موضع النزول، وقال المفضّل: الهبوط: الخروج عن البلد، وهو أيضا الدخول فيها، من الأضداد. ويقال في انحطاط المنزلة مجازا، ولهذا قال الفرّاء  : والهبوط: الذل  .",2]]],[9,9,[["بَعْضُكُمْ","أصل بعض مصدر بعض يبعض بعضا، أي قطع  ، ويطلق على الجزء ويقابله كلّ، وهما معرفتان لصدور الحال منهما في فصيح الكلام، قالوا: مررت ببعض قائما، وبكلّ جالسا، وينوى فيهما الإضافة، ومن ثمة لا تدخل عليهما أداة التعريف، ولذلك خطّؤوا من قال «بدل البعض من الكلّ» .",2]]],[11,11,[["عَدُوٌّ","العداوة: مجاوزة الحدّ. يقال: عدا فلان طوره، إذا جاوزه، وقيل: هي اختلاف القلوب والتباعد بها، من عدوتي الجبل وهما طرفاه، سمّيا بذلك لبعد ما بينهما، وقيل: من عدا، أي ظلم، وكلها متقاربة معنى.والعدوّ يكون للواحد والاثنين والجمع والمذكّر والمؤنّث.",2]]],[15,15,[["مُسْتَقَرٌّ","مستفعل من القرار، وهو اللّبث والإقامة، وهومشترك بين المصدر واسمي  الزّمان والمكان والمفعول، واستفعل فيه بمعنى فعل إذ استقرّ وقرّ بمعنى.",2]]],[16,18,[["وَمَتاعٌ إِلى حِينٍ","[أي متعة]  إلى أجل، وحِينٍ:غاية ووقت أيضا، وزمان غير محدود، وقد يجيء محدودا  . المتاع: البلغة.وهو مأخوذ من متع النّهار، إذا ارتفع فيطلق على ما يتحصّل للإنسان من عرض الدنيا وعلى الزاد وعلى الانتفاع بالنساء  وعلى الكسوة وعلى التعمير.وقوله «غاية» أي في هذا الموضع بواسطة «إلى» الموضوعة لذلك.والوقت أعم من الزمان. وقوله «غير محدود» إلى آخره، أي الحين اسم لزمان مبهم، وقد يتعيّن بالقرائن.",2]]]],"42":[[0,0,[["فتلقى","اخذ كان الله تعالى اوحى اليه كلمات فاستغفره بها والكلمات",1]]],[1,1,[["آدَمَ ،","اسم أعجميّ، كآزر، وغابر، ممنوع الصرف للعلميّة  والعجمة. ومن زعم أنه مشتقّ من الأدمة، وهي كالسّمرة، أو من أديم الأرض وهو وجهها، فغير صواب لأن الاشتقاق لا يكون في الأسماء الأعجمية.وقيل هو عبري من الأدام وهو التّراب  . ومن زعم أنه فاعل من أديم الأرض فالهمزة الثانية عنده زائدة بخلاف الأول فعنده الأولى هي الزائدة فخطؤه ظاهر لعدم صرفه.وأبعد الطّبريّ  في زعمه أنه فعل رباعي سمّي به.",2]]],[5,10,[["فَتابَ عَلَيْهِ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ","التّوّاب هو الله يتوب على العباد، والتّوّاب من الناس: التائب  وأصل التّوبة الرّجوع. تاب يتوب توبا وتوبة ومتابا، فإذا عدّي بعلى ضمّن معنى العطف، وهي من العبد رجوع وإقلاع عن الذّنب، ومن الله قبول ورحمة.",2]]]],"43":[[9,9,[["تَبِعَ","بمعنى لحق، وبمعنى تلا، وبمعنى اقتدى.",2]]],[12,12,[["خَوْفٌ","أي فزع، والخوف: توقّع مكروه في المستقبل، وضده الأمن.",2]]],[16,16,[["يَحْزَنُونَ","الحزن: غلظ الهمّ لفوت المرغوب في الماضي والحال، مأخوذ من الحزن وهو ما غلظ من الأرض، وضده السّرور.",2]]]],"45":[[1,1,[["إِسْرائِيلَ","يعقوب عليه السلام  ممنوع الصّرف للعلميّة والعجمة، وقد ذكروا أنه مركب من إسرا وهو العبد وإيل اسم من  أسماء الله تعالى فكأنّه عبد الله، وذلك باللسان العبراني فيكون مثل جبرئيل وميكائيل وإسرافيل وعزرائيل عليهم السلام، وقيل غير ذلك.",2]]],[2,2,[["اذْكُرُوا","الذّكر بضم الذال وكسرها لغتان بمعنى واحد، وقال الكسائي  : بالكسر ضدّ الصّمت، وبالضّم ضدّ النّسيان وهو بمعنى التّيقّظ والتّنبّه.ويقال: اجعله منك على ذكر.",2]]],[3,3,[["نِعْمَتِيَ","النّعمة: اسم للشيء المنعم به، وكثيرا ما تجيء فعل بمعنى المفعول كالذّبح والنّقض والطّحن.",2]]],[7,7,[["أَوْفُوا","أدّوه وافيا تامّا. الوفاء: تمام الشيء، ووفى وأوفى ووفّى لغات بمعنى واحد.",2]]],[12,12,[["فَارْهَبُونِ","خافون، وإنما حذفت الياء لأنها رأس آية، ورؤوس الآي ينوى الوقف عليها. والوقف على الياء يستثقل فاستغنوا عنها بالكسرة  والرّهب والرّهب والرّهبة: الخوف.",2]]]],"46":[[3,3,[["مُصَدِّقاً","والتّصديق: اعتقاد مطابق للمخبر به. وقيل: قول نفساني تابع للاعتقاد المذكور، وهما قولان للأشعري  أرجحهما الثاني. والتكذيب يقابله.",2]]],[8,10,[["أول كافر به","لانه اشد فى العناد",1]]],[13,13,[["بِآياتِي","آيات: علامات، وعجائب أيضا، وآية من القرآن:كلام متّصل إلى انقطاعه. وقيل: إنّ معنى آية من القرآن جماعة حروف، يقال:خرج القوم بآياتهم، أي بجماعتهم  وفي حدّ الآية من القرآن عسر. والتّعريفان لا يطّردان ولا ينعكسان.",2]]],[14,14,[["ثَمَناً","هو العوض المبذول في مقابلة العين المبيعة.",2]]]],"47":[[1,1,[["تلبسوا","بمعنى تخلطوا فكانو يقولون فن صفة النبى صلى الله عليه وسلم ليس",1]]]],"48":[[4,4,[["وَارْكَعُوا","الركوع له معنيان في اللغة: أحدهما: التّطامن  والانحناء، وهو قول الخليل  وأبي زيد. والثاني: الذّلة والخضوع  وهو قول المفضّل والأصمعي  .",2]]]],"49":[[2,2,[["بِالْبِرِّ","الدّين والطّاعة  وله معان أخر: الصّلة. وبررت أبرّ برّا فأنا بارّ وبرّ.",2]]],[3,3,[["وَتَنْسَوْنَ","النّسيان: ضدّ الذّكر، وهو السّهو الحادث بعد حصول العلم، ويطلق أيضا على التّرك، وهو المراد هنا. وضدّه الفعل.",2]]],[6,6,[["تَتْلُونَ","تقرءون، سمّيت القراءة تلاوة لأن الآيات والكلمات والحروف يتلو بعضها بعضا في الذّكر. والتّلو: التّبع.",2]]],[9,9,[["تَعْقِلُونَ","العاقل: الذي يحبس نفسه ويردّها عن هواها. ومن هذا قولهم: اعتقل لسان فلان، إذا حبس ومنع  من الكلام  وللعقل محامل منها الإدراك المانع من الخطأ، وهو نقيض الحمق، وقيل: ضدّ الجهلوأصله المنع، وقيل: الشّدّ لأنه يشدّ على المعنى الذي يفهمه في قلبه.",2]]]],"50":[[1,1,[["بِالصَّبْرِ","حبس النّفس على المكروه، وقيل: حبسها عما تسارع إليه.",2]]],[7,7,[["الْخاشِعِينَ","المتواضعين  والخشوع: قريب من الخضوع، وأصله اللّين والسهولة. وقيل: الاستكانة والتذلل، وقال اللّيث  :الخضوع في البدن  ، والخشوع في البدن والبصر والصّوت  .",2]]]],"51":[[1,4,[["يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ","أي يوقنون  ، ويظنّون أيضا:يشكّون، والظّن من الأضداد  وهو حقيقة في التّردد بين جائزين، مجاز في اليقين.",2]]]],"52":[[10,10,[["العالمين","عالمو زمانهم",1]]]],"53":[[3,3,[["تجزي","بمعنى تقضى",1]]],[12,15,[["وَلا يُؤْخَذُ مِنْها عَدْلٌ","أي فدية، ومثله وَإِنْ تَعْدِلْ كُلَّ عَدْلٍ لا يُؤْخَذْ مِنْها   الأخذ: ضدّ التّرك، والأخذ أيضا: القبض والإمساك.",2]]],[18,18,[["يُنْصَرُونَ","النّصر: العون.",2]]]],"54":[[1,1,[["نَجَّيْناكُمْ","النّجاة: التّنجية من الهلكة بعد الوقوع فيها، والأصل الإلقاء بنجوة.",2]]],[3,4,[["آلِ فِرْعَوْنَ","قومه وأهل دينه  وقيل: الآل من يؤول إليك من قرابة أو رأي أو مذهب، فألفه بدل من واو، وتصغيره أويل، قال الأخفش  : لا تضاف إلّا إلى الرئيس الأعظم، نحو آل محمد- صلّى الله عليه وسلّم-، وآل فرعون لأنه رئيسهم في الضلالة، وفرعون لا ينصرف للعلميّة والعجمة، قال البيهقيّ  : هو اسم لمن ملك القبط ومصر، وقال غيره: علم لمن ملك العمالقة، كما قيل قيصر لمن ملك الرّوم، وكسرى لمن ملك الفرس، والنجاشي لمن ملك الحبشة، وتبّع لمن ملك اليمن.",2]]],[5,5,[["يسومونكم","اى يولونكم",1]]],[6,7,[["سُوءَ الْعَذابِ","أشدّه. والسوء: اسم جامع للآفات، وهو مصدر ساء يسوء سوءا، أي أحزنه ثم استعمل في كل ما يستقبح. يقال: أعوذ باللهمن سوء الخلق وسوء الفعل، يراد قبيحهما.",2]]],[10,10,[["ويستحيون","يستبقون",1]]],[14,14,[["بَلاءٌ","على ثلاثة أوجه: نعمة، واختبار، ومكروه  وقيل:البلاء في الأصل: الاختبار، بلاه يبلوه بلاء، ثم صار يطلق على المكروه والشّدة.ويقال: أبلى بالنّعمة وبلي بالشدة. وقد يدخل أحدهما على الآخر فيقال: بلاه بالخير وأبلاه بالشّرّ.",2]]]],"55":[[1,3,[["فَرَقْنا بِكُمُ الْبَحْرَ","فلقناه لكم  وأصل الفرق: الفصل بين الشّيئين، والفرق ضد الجمع، وضد الفصل الوصل. والشّق والصّدع وضدهما اللأم.والتمييز ضده الاختلاط. وقيل: يقال فرّق في المعاني وفرّق في الأجسام وهو غير مستقيم.",2]]],[9,9,[["تَنْظُرُونَ","أي تبصرون.",2]]]],"56":[[1,1,[["وعدنا","وعد في الخير والشّر، والوعد في الخير، وأوعد في الشر، وكذلك الإيعاد والوعيد.",2]]],[2,2,[["مُوسى","اسم أعجميّ لا ينصرف للعجمة والعلميّة، ويقال:هو مركّب من «مو» وهو الماء و «شا» وهو الشّجر، فلما عرّب أبدلوا شينه سينا.",2]]],[6,6,[["اتَّخَذْتُمُ","الاتّخاذ: افتعال من الأخذ.",2]]]],"57":[[1,2,[["عَفَوْنا عَنْكُمْ","أي محونا عنكم ذنوبكم، ومنه عَفَا اللَّهُ عَنْكَ  أي محا الله عنك ذنوبك  وعفا عنك  بين معان.",2]]],[7,7,[["تَشْكُرُونَ","أي تجازون على الإحسان، يقال: شكرت الرّجل إذا جازيته على إحسانه إمّا بفعل وإما بثناء، والله تعالى اسمه شكور، أي مثيب عباده على أعمالهم   والشّكر هو الثّناء على إسداء النّعم وقيل: إظهار النّعمة.",2]]]],"58":[[4,4,[["والفرقان","النصر",1]]]],"59":[[12,12,[["بارِئِكُمْ","خالقكم  . يقال إنّ خلق وبرأ وأنشأ وأبدع نظائر.",2]]]],"60":[[7,7,[["نَرَى","نبصر.",2]]],[9,9,[["جَهْرَةً","علانية  ومنه الجهر ضد السّر.",2]]]],"62":[[2,2,[["الْغَمامَ","سحاب أبيض، سمّي بذلك لأنّه يغمّ السماء، أي يسترها  وقيل: السحاب هو اسم جنس بينه وبين مفرده التاء، يقال: غمامة وغمام.",2]]],[5,5,[["المن","شىء يقع على الشجر",1]]],[6,6,[["والسلوى","طا ئر",1]]],[9,9,[["طَيِّباتِ","الطّيّب فيعل، من طاب يطيب، وهو اللذيذ.",2]]]],"63":[[4,4,[["القرية","بيت المقدس",1]]],[12,12,[["سجدا","اي ركعا",1]]],[14,14,[["حطة","حط عنا ذنوبنا",1]]],[15,15,[["نَغْفِرْ","نستر.",2]]],[17,17,[["خَطاياكُمْ","جمع خطيّة، وهي فعيلة من الخطأ وهو العدول عن القصد، يقال: خطئ الشيء: أصابه بغير قصد، وأخطأ إذا تعمّد.",2]]],[19,19,[["الْمُحْسِنِينَ","جمع محسن، وهو اسم فاعل من أحسن، إذا أتى بالحسن. وأحسن الشيء إذا أتى به حسنا، وأحسن إلى فلان: أسدى إليه خيرا.والإحسان والإنعام والإفضال نظائر.",2]]]],"64":[[0,0,[["فَبَدَّلَ","التّبديل: تغيير الشيء بآخر، تقول: هذا بدل هذا أي عوضه.",2]]],[12,12,[["رِجْزاً","الرّجز: العذاب بلغة بليّ  كقوله تعالى: فَلَمَّا كَشَفْنا عَنْهُمُ الرِّجْزَ  أي العذاب   وتكسر راؤه وتضمّ  .",2]]]],"65":[[1,1,[["اسْتَسْقى","طلب السّقيا.",2]]],[8,8,[["فَانْفَجَرَتْ","الانفجار: انصداع شيء من شيء، ومنه الفجر والفجور.",2]]],[17,17,[["مَشْرَبَهُمْ","هو مفعل من الشّرب يكون للمصدر والزّمان والمكان.",2]]],[24,24,[["تَعْثَوْا","العثوّ والعيث والعثيّ  : أشدّ الفساد  يقال: عثا يعثو عثوّا، وعثي  يعثى عثيّا، وعاث يعيث عيثا وعيوثا ومعاثا، وعثّ يعثّ كذلك، ومنه عثّة الصّوف وهي السّوسة التي تلحسه.",2]]]],"66":[[6,6,[["طَعامٍ","وهو اسم لما يطعم، كالعطا: اسم لما يعطى.",2]]],[7,7,[["واحِدٍ","الواحد لا يتبعّض ولا يضمّ إليه بأن يقال: وحد يحد وحدا وحدة إذا انفرد.",2]]],[8,8,[["فَادْعُ","الدّعاء: التّصويت باسم المدعوّ على سبيل النّداء.",2]]],[14,14,[["تُنْبِتُ","الإنبات: هو الإخراج لما من شأنه النمو.",2]]],[18,18,[["وَقِثَّائِها","القثّاء: اسم جنس واحده قثّاءة، بضمّ القاف وكسرها، وهو هذا المعروف. وقال الخليل: هو الخيار، ويقال: أرض مقثأة: كثيرة القثّاء  .",2]]],[19,19,[["وَفُومِها","الفوم: الحنطة والخبز جميعا، يقال: فوّموا: أي اختبزوا. ويقال: الفوم: الحبوب. ويقال: الفوم: الثّوم، أبدلت الفاء ثاء كما قالوا جدث وجدف للقبر [زه] وقيل: الفوم: الحنطة فقط، وقيل: الحبوب التي تخبز، وقيل: السّنبلة. وقيل: الحبوب التي تؤكل، وقيل: عقدة في البصل، وكلّ قطعة عظيمة في اللحم وكل لقمة كبيرة، وقيل: الحمّص. والقول بأن الفاء بدل من الثاء معزوّ إلى الكسائي والفرّاء والنّضر بن شميل  وغيرهم.",2]]],[26,26,[["أَدْنى","أفعل التفضيل من الدنوّ، وهو القرب، وقال الأخفش:من الدناءة وهي الخسّة والرّداءة خفّفت الهمزة بإبدالها ألفا. وقيل: من الدّون، أي أحطّ في المنزلة، وأصله أدون فقلبت فصار وزنه أفلع.",2]]],[31,31,[["مِصْراً","المصر: البلد، مشتقّ من مصرت الشاة أمصرها مصرا:حلبت كلّ شيء في ضرعها. وقيل: المصر: الحدّ بين الأرضين، وقرئ بغير تنوين  ، فالمراد به مصر فرعون، واستشكل على التنوين: هل المراد مصر، غيرمعيّن لا من الشام ولا من غيره، أو من أمصار الشام أو معيّن هو بيت المقدس، أو مصر فرعون، أقوال  .",2]]],[36,39,[["وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ","أي ألزموها، والذّلّة:الذلّ وهو الصّغار، والمسكنة مصدر المسكين. وقيل: المسكنة: فقر النّفس. لا يوجد يهوديّ موسر، ولا فقير غنيّ النّفس وإن تعمّد  لإزالة ذلك عنه   والذّل:الخضوع وذهاب الصّعوبة، وهو مصدر ذلّ يذلّ ذلّة، وقيل: الذّلة: هيئة من الذل، كالجلسة.وَالْمَسْكَنَةُ: مفعلة  من السّكون. قيل: ومنه سمّي المسكين لقلّة حركاته وفتور نشاطه.",2]]],[40,43,[["وَباؤُ بِغَضَبٍ مِنَ اللَّهِ","انصرفوا بذلك، وقيل: استوجبوا بلغة جرهم  ولا يقال: باء بكذا إلا في الشّرّ، ويقال: باء بكذا إذا أقرّ به  وقيل غير ذلك.",2]]],[52,53,[["بغير الحق","بغير جرم",1]]],[56,56,[["عَصَوْا","العصيان: عدم الانقياد للأمر والنّهي.",2]]]],"67":[[4,4,[["هادُوا","تهوّدوا، أي صاروا يهودا. وهادوا: تابوا أيضا، من قوله: إِنَّا هُدْنا إِلَيْكَ  أي: تبنا  وسيأتي الكلام على لفظ يهود  .",2]]],[5,5,[["وَالنَّصارى","جمع نصران ونصرانة، مثل ندمان وندمانة، قاله سيبويه «7» . وإنه لا يستعمل في الكلام إلا بياء النسب كلحيان. وقال الخليل: واحد النّصارى نصريّ كمهريّ ومهارى «8» . وقيل: هو منسوب إلى نصرة، وهي قرية نزلهاعيسى- على نبينا وعليه الصلاة والسّلام- وقال قتادة: نسبوا إلى ناصرة  ، وهي قرية نزلوها، فعلى هذا يكون من تغيير النّسب.",2]]],[6,6,[["والصابئين","صنف من النصارى",1]]],[15,15,[["أَجْرُهُمْ","هو مصدر أجر يأجر، ويطلق على المأجور به، وهو الثّواب.",2]]]],"68":[[5,5,[["الطُّورَ","الجبل   وافقت لغة العرب في هذا الحرف لغة السّريانية  أي اسم لكل جبل. وقيل: الجبل المنبت دون غيره. وقيل: الجبل الذي ناجى عليه الله موسى- على نبينا وعليه أفضل الصلاة والسلام- وأصله الناحية، ومنه طور الدار.",2]]],[9,9,[["بقوة","اى بجد واجتهاد",1]]]],"69":[[1,1,[["تَوَلَّيْتُمْ","التّولّي: الإعراض بعد الإقبال.",2]]]],"70":[[2,6,[["الذين اعتدوا منكم في السبت","اخذو فيه الحيتان وقد حرم عليهم ذلك والخاسئ المبعد",1]]],[11,11,[["خاسِئِينَ","أي باعدين ومبعدين أيضا، أو صاغرين بلغة كنانة  ، وهو إبعاد بالمكروه، ويقال: خسأت الكلب وخسأ الكلب  والخسوء:الصّغار والطّرد.",2]]]],"71":[[0,0,[["فجعلناها","يعنى العقوبه",1]]],[1,1,[["نكالا","اى عبرة",1]]],[2,4,[["لما بين يديها","من الذنوب",1]]],[5,6,[["وما خلفها","وما عملو بعدها",1]]],[7,7,[["مَوْعِظَةً","تخويف سوء العاقبة [زه] وهي مفعلة من الوعظ، وهو الادّكار في الخير بما يرقّ له القلب.",2]]]],"72":[[9,9,[["بَقَرَةً","الأنثى من الحيوان المعروف، وقد يقع على الذّكر، قيل: سمّيت بذلك لأنها تبقر الأرض، أي تشقّها للحرث.",2]]],[14,14,[["أَعُوذُ","أعتصم.",2]]]],"73":[[4,4,[["بَيْنَ","ظرف مكان متوسط التصرّف.",2]]],[14,14,[["فارِضٌ","مسنّة  أي التي انقطعت ولادتها من الكبر، سمّيت بذلك لأنّها فرضت سنّها، أي قطعتها وبلغت آخرها.",2]]],[16,16,[["بِكْرٌ","صغيرة، وزاد بعضهم: التي  لم تلد من الصّغر، وقال ابن قتيبة: التي ولدت ولدا واحدا  .",2]]],[17,17,[["عَوانٌ","نصف بين الصّغيرة والكبيرة  وقيل: التي ولدت بطنا أو بطنين.",2]]]],"74":[[13,15,[["صَفْراءُ فاقِعٌ لَوْنُها","ناصع لونها، ويجوز أن تكون صفراء وصفر من الصّفرة  الناصع: الخالص من كل شيء صفرة كانت أو غيرها. وقيل:الفقوع: أشد ما يكون من الصّفرة وأبلغه، يقال: أصفر فاقع ووارس، كما يقال:أسود حالك وحانك  ، وأبيض يقق ولهق، وأحمر قانئ، وأخضر ناضر ومدهامّ، وأزرق خطبانيّ  .",2]]],[16,16,[["تسر","بمعنى تعجب",1]]]],"75":[[10,10,[["تَشابَهَ","يشبه بعضه بعضا.",2]]]],"76":[[6,8,[["ذَلُولٌ تُثِيرُ الْأَرْضَ","أي تذلّلها  للحرث [زه] يقال في الدّوابّ: دابّة ذلول بيّنة الذّل بكسر الذال، وفي الناس يقال: رجل ذليل بيّن الذّل، بضم الذّال وقيل: الذّلول: الرّيّض الذي زالت صعوبته. والإثارة: الاستخراج والقلقلة من مكان إلى مكان.",2]]],[9,11,[["لا تَسْقِي الْحَرْثَ","أي لا يسنى بها لتسقي الزرع  أي ليست بناضحة  تسقي الأرض المزروعة.",2]]],[12,12,[["مسلمة","من العيوب",1]]],[13,15,[["لا شية فيها","اى ليس فيها لون يخالف لفون سائرها",1]]],[17,17,[["الْآنَ","ظرف زمان خص جميعه أو بعضه.",2]]]],"77":[[3,3,[["فادارأتم","تدافعتم والقى بعضكم على بعض وهذه الاية مقدمة فى المعنى على قصة البقره",1]]]],"79":[[1,2,[["قَسَتْ قُلُوبُكُمْ","يبست وصلبت، وقلب قاس وجاس وعاس وعات، أي صلب يابس جاف عن الذّكر غير قابل له   والقساوة: غلظ القلب وصلابته، يقال: قسا يقسو قسوا وقسوة وقساوة وحسّا وعسّا متقاربة.",2]]]],"80":[[0,0,[["فَتَطْمَعُونَ","الطّمع: رجاء الشّيء والرغبة فيه.",2]]],[6,7,[["فَرِيقٌ مِنْهُمْ","طائفة منهم.",2]]],[12,12,[["يُحَرِّفُونَهُ","يقلبونه ويغيّرونه.",2]]]],"81":[[13,16,[["بما فتح الله عليكم","اى قضى وكان ناس من اليهود يحدثون المؤمنين بما عذبوا به وقيل بما علمكم الله",1]]]],"83":[[0,0,[["أَمانِيَّ","جمع أمنيّة، وهي التّلاوة، ومنه قوله تعالى:إِذا تَمَنَّى أَلْقَى الشَّيْطانُ فِي أُمْنِيَّتِهِ  أي إذا تلا ألقى الشّيطان في تلاوته.والأمانيّ: الأكاذيب أيضا، ومنه قول عثمان رضي الله عنه: «ما تمنّيت منذأسلمت»  : أي ما كذبت. وقول بعض العرب لابن دأب  وهو يحدّث: «هذا  شيء رويته أم شيء تمنّيته؟» أي افتعلته.والأماني أيضا: ما يتمنّاه الإنسان ويشتهيه.",2],["أُمِّيُّونَ","الذين لا يكتبون، واحدهم أمّيّ منسوب إلى الأمّة الأمّيّة التي هي على أصل ولادات أمّهاتها، لم تتعلّم الكتابة ولا قراءتها  وقيل:منسوب إلى الأمّ لأنه تربّى معها ولم تربّه الرّجال فيعلم ما تعلمه الرّجال.",2]]]],"84":[[0,0,[["وَيْلٌ","كلمة تقال عند الهلكة  وقيل: واد في جهنّم.وقال الأصمعيّ: ويل: قبوح، وويس: استصغار، وويح: ترحّم [زه] وقيل: واد من صديد في جهنّم. وقيل: الشّديد من العذاب. وقيل: الهلاك يستعمل لمن لا يرجى خلاصه.",2]]]],"85":[[2,2,[["تَمَسَّنَا","تصيبنا، والمسّ: الجمع بين الشّيئين على نهاية القرب.",2]]],[6,6,[["مَعْدُودَةً","من العدد.",2]]]],"86":[[0,3,[["بلى من كسب سيئة","اى شركا",1]]]],"88":[[10,10,[["حُسْناً","الحسن والحسن  لغتان كالبخل والبخل وقيل:الحسن وصف أي قولا حسنا، والحسن مصدر، أي قولا ذا حسن.",2]]],[14,14,[["الْمَساكِينِ","جمع مسكين، هو مفعيل من السّكون وهو الذي سكّنه الفقر، أي قلّل حركته، قال يونس  : المسكين: الذي لا شيء له، والفقير: الذي له بعض ما يقيمه  ، وقال الأصمعيّ  : بل المسكين أحسن من الفقير «7» لأنّ الله تعالى قال: أَمَّا السَّفِينَةُ فَكانَتْ لِمَساكِينَ «8» ، فأخبر أنّالمسكين له سفينة من سفن البحر، وهي تساوي جملة   وفي  الأسوأ حالا منهما مذهبان للعلماء، وما احتج به في دلالته نزاع.",2]]]],"89":[[3,5,[["لا تسفكون دماءكم","اى لايسفك بعضكم دم بعض وكانت قريظة حلفاء الاوس والنضير حلفاء الخزرج وكانوا يقاتلون مع حلفائهم فاذا اسر رجل من الفريقين جمعوا له حتى يفدوه فتعيرهم العرب وتقول كيف تقاتلونهم وتفدونهم فيقولون امرنا ان نفديهم وحرم علينا قتلهم فتقول العرب فلم تقاتلونهم فيقولون نستحييى ان يستذل حلفاؤنا",1]]],[12,12,[["أَقْرَرْتُمْ","اعترفتم، والاعتراف: الإخبار على طريق الإيجاب بنعم.",2]]]],"90":[[10,11,[["تَظاهَرُونَ عَلَيْهِمْ","تعاونون عليهم  . والمظاهرة والمعاونة واحد، وأصله تتظاهرون فأدغم التاء بعض وحذفها بعض» .",2]]],[12,12,[["بِالْإِثْمِ","بما فيه إثم. والإثم: الفعل الذي يستحق عليه اللّوم.",2]]],[13,13,[["الْعُدْوانِ","هو التّعدي والظّلم، وهو مجاوزة الحدّ. وقيل:العدوان: الإفراط في الظّلم.",2]]],[16,16,[["أُسارى","جمع أسرى، وأسرى جمع أسير، وهو جمع الجمع، وأصله الشّدّ بالأسر وهو القدّ.",2]]],[17,17,[["تفدوهم","الفداء: البدل من الشيء صيانة له. وقيل: إنّ فادى وفدى بمعنى.",2]]],[22,24,[["أفتؤمنون ببعض الكتاب","وهو فداء الاسارى",1]]],[25,26,[["وتكفرون ببعض","وهو الاخراج والقتل",1]]],[28,28,[["جَزاءُ","الجزاء: المقابلة على الخير بالثّواب، وعلى الشّر بالعقاب.",2]]],[34,34,[["خِزْيٌ","هوان، وهلاك أيضا  . قال ابن السّرّاج  :يصلح أن يكون أصله من الخزاية، وهو أن يقف موقفا يستحيي منه.",2]]],[40,40,[["يُرَدُّونَ","يصرفون. والرّدّ: الرّجع.",2]]],[42,43,[["أَشَدِّ الْعَذابِ","هو الذي لا روح فيه ولا فرج. وقيل: إلى أشد من عذاب الدّنيا.",2]]]],"92":[[4,4,[["وقفينا","اى اتبعنا",1]]],[7,7,[["بِالرُّسُلِ","جمع رسول، وهو المؤدّي عن الله ما أوحاه إليه، المبان عن غيره بالمعجزة الدالّة على صدقه. واشتقاقه من الرّسل وهو اللّين.",2]]],[13,13,[["أَيَّدْناهُ","قوّيناه  والأيد والأدّ: القوّة.  .",2]]],[14,15,[["روح القدس","جبريل والقدس الطهاره",1]]],[21,22,[["تَهْوى أَنْفُسُكُمُ","أي تميل، والهوى في المحبّة إنما هو ميل النّفس إلى من تحبّه.",2]]]],"93":[[1,2,[["قلوبنا غلف","اى ذوات غلف فما نفهم ما تقول",1]]],[4,5,[["لَعَنَهُمُ اللَّهُ","طردهم وأبعدهم  واللّعن والطّرد واحد.وذئب لعين أي طريد.",2]]]],"94":[[12,12,[["يستفتحون","يستنصرون باسم محمد صلى الله عليه وسلم",1]]]],"95":[[1,3,[["اشتروا به أنفسهم","باعوها",1]]],[9,9,[["بغيا","اى حسدا والمعنى",1]]],[20,21,[["فباؤوا بغضب","لتبديلهم التورات",1]]],[22,23,[["على غضب","لتكذيبهم بمحمد صلى الله عليه وسلم",1]]],[26,26,[["مُهِينٌ","مذل: والهوان: الاستخفاف.",2]]]],"98":[[14,17,[["وأشربوا في قلوبهم العجل","اى سقوا حب العجل",1]]],[20,20,[["بِئْسَما","كلمة موضوعة لإنشاء الذّمّ.",2]]]],"99":[[6,6,[["عِنْدَ","ظرف لاستغراق الزمان المستقبل.",2]]]],"100":[[4,5,[["قَدَّمَتْ أَيْدِيهِمْ","أسلفوا من الأعمال القبيحة، والتقديم تحصّل شيء قبل شيء.",2]]]],"101":[[1,1,[["أَحْرَصَ","أفعل التّفضيل من الحرص، وهو شدّة الطّلب  .",2]]],[5,7,[["ومن الذين أشركوا","اى احرص من المشركين وهم المجوس",1]]],[8,8,[["يَوَدُّ","مضارع ودّ، أي تمنّى، وودّ: أحبّ أيضا.",2]]],[11,11,[["يُعَمَّرُ","يطول عمره.",2]]],[14,15,[["وما هو","يعنى التعمير",1]]],[19,20,[["أن يعمر","قال الزجاج جعل مبنيا عن هو",1]]]],"102":[[4,4,[["لِجِبْرِيلَ","اسم غير منصرف للعجمة والعلميّة، وفيه لغات نظمها ابن مالك فقال:جبريل جبريل جبرائيل جبرئل وجبرئيل وجبرال وجبرين  ويقال جبرين بالفتح.قلت: وقد بلّغ لغاته ابني محمد- رحمه الله تعالى- في كتاب «الغرر المضية» إلى قريب الثلاثين، قال: وغالبها قرئ به في الشاذ وبيّنه. ويقال: إنه مركّب من جبر وهو العبد بالسّريانية، ومن إيل وهو اسم الله تعالى. وكذلك ميكائيل.",2]]]],"105":[[3,3,[["نَبَذَهُ","تركه وألقاه. والنّبذ: الطّرح على وجه الاستحقار.",2]]]],"107":[[2,2,[["تتلو","بمعنى تلت",1]]],[4,4,[["على","بمعنى فى",1]]],[15,15,[["السحر","قال الزجاج وكانا يعلمان الناس السحر ويامرون باجتنابه وجائز ان يكون الله امتحن الناس بالملكين فمن قبل التعليم كفر",1]]],[16,19,[["وما أنزل على الملكين","فيها قولان احدهما انها معطوفه على",1]]],[20,20,[["بِبابِلَ","قيل: الكوفة، وقيل: نصيبين، وقيل: جبل دماوند  ، وقيل: وهدة من الأرض.",2]]],[21,22,[["هارُوتَ وَمارُوتَ","قيل: ملكان، وقيل: رجلان، وقيل:شيطانان. وعلى الأول فقيل هما جبريل وميكائيل، وقيل غير هما وهو المشهور.",2]]],[31,31,[["فِتْنَةٌ","بلاء واختبار.",2]]],[49,50,[["بِإِذْنِ اللَّهِ","أي بعلمه. والإذن والأذن بمعنى، كالشّبه والشّبه، وقيل: بالفتح المصدر وبالكسر الاسم كالحذر والحذر.",2]]],[56,57,[["ولقد علموا","يعنى اليهود",1]]],[58,59,[["لمن اشتراه","اى اختار السحر",1]]],[65,65,[["خَلاقٍ","نصيب [زه] وقيل: دين، وقيل: خير.",2]]],[68,70,[["شَرَوْا بِهِ أَنْفُسَهُمْ","أي باعوها به، [زه] بلغة هذيل  .",2]]]],"108":[[4,4,[["لَمَثُوبَةٌ","ثواب.",2]]]],"109":[[5,5,[["راعنا","كلمة كان المنافقون يقولونها لرسول الله صلى الله عليه وسلم يريدون انت ارعن",1]]],[7,7,[["انظرنا","يعني انتظرنا",1]]]],"110":[[17,17,[["يَخْتَصُّ","الاختصاص بالشيء: الانفراد به.",2]]],[22,24,[["ذُو الْفَضْلِ الْعَظِيمِ","صاحب الثواب الكبير.",2]]]],"111":[[0,3,[["ما نَنْسَخْ مِنْ آيَةٍ","النّسخ على ثلاثة معان:أحدهن: نقل الشيء من موضع إلى موضع، كقوله تعالى: إِنَّا كُنَّا نَسْتَنْسِخُ ما كُنْتُمْ تَعْمَلُونَ  .والثاني: نسخ الآية بأن يبطل حكمها ويكون لفظها متروكا، كقوله: قُلْ لِلَّذِينَ آمَنُوا يَغْفِرُوا لِلَّذِينَ لا يَرْجُونَ أَيَّامَ اللَّهِ  نسخت بقوله: فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ  .والثالث: أن تقلع الآية من المصحف ومن قلوب الحافظين، يعني في زمن النبي صلّى الله عليه وسلّم.ويقال: ما نَنْسَخْ مِنْ آيَةٍ أي نبدّل، [ومنه قوله عز وجل]  : وَإِذا بَدَّلْنا آيَةً مَكانَ آيَةٍ   له في اللغة معنيان مشهوران: الإزالة والنّقل. وقيل: هو مقول عليهما بالاشتراك فيكون حقيقة فيهما أو حقيقة في أحدهما «7» مجازا في الآخر، ثلاثة مذاهب. وحقيقته العرفية مبينة في أصول الفقه، ويقع في القرآن على ثلاثة أوجه: نسخ الرّسم والحكم، ونسخ أحدهما دون الآخر.",2]]],[5,5,[["ننسها","اى نؤخر نسخها",1]]],[6,8,[["نأت بخير منها","اى اسهل",1]]],[10,10,[["أو مثلها","في المنعه والثواب",1]]]],"112":[[0,0,[["وَلِيٍّ","أي الوالي  . والوليّ: المقيم بالأمر.",2]]],[16,16,[["نَصِيرٍ","ناصر.",2]]]],"113":[[5,7,[["كما سئل موسى","وهو قولهم",1]]],[16,17,[["سواء السبيل","وسطه",1]]]],"114":[[12,14,[["من عند أنفسهم","اى من قبل النفس لا انه عندهم حق",1]]]],"116":[[4,7,[["إلا من كان هودا","هذا قول اليهود",1]]],[9,9,[["أو نصارى","قول النصارى والهود جمع هائد",1]]],[11,11,[["أَمانِيُّهُمْ","أكاذيبهم وأباطيلهم، بلغة قريش  .",2]]],[13,13,[["هاتُوا","أحضروا وقرّبوا.",2]]],[14,14,[["بُرْهانَكُمْ","أي حجّتكم، يقال: قد برهن قوله، أي بيّنه بحجّته  ، وقال ابن عيسى  : البرهان: بيان عن معنى يشهد بمعنى آخر حقّ في نفسه وشهادته.",2]]]],"117":[[0,0,[["بلى","رد عليهم",1]]],[1,3,[["من أسلم وجهه","اى اخلص دينه",1]]]],"118":[[15,19,[["كذلك قال الذين لا يعلمون","هم مشركو العرب قالوا يعنى لمحمد صلى الله عليه وسلم واصحابه لستم على شيء",1]]]],"119":[[14,20,[["ما كان لهم أن يدخلوها إلا خائفين","ظاهرة الخير ومعناه الامر وتقديره خذوا فى جهادهم ليخافو",1]]]],"120":[[5,7,[["فثم وجه الله","اى علمه",1]]],[10,10,[["واسِعٌ","جواد يسع لما يسأل. ويقال: الواسع: المحيط بعلم كل شيء كما قال عز وجل: وَسِعَ كُلَّ شَيْءٍ عِلْماً   وقيل: قادر.وقيل: واسع [الرحمة، ولذلك رخّص في]  الشريعة.",2]]]],"121":[[13,13,[["قانِتُونَ","أي مطيعون. وقيل: مقرّون بالعبوديّة. والقنوت على وجوه: الطّاعة، والقيام في الصّلاة، والدّعاء، والصّمت. قال زيد بن أرقم  : «كنا نتكلّم في الصلاة حتى نزلت وَقُومُوا لِلَّهِ قانِتِينَ  فأمسكنا عن الكلام»   وحديث زيد متّفق عليه  . ومعاني القنوت تزيد على عشر وقد نظمتها في قولي:معاني قنوت: طاعة ودوامها إقامتها، سكت خشوع عبودية صلاة قيام طوله، وعبادة دعاء وإقرار وإخلاص ذي النيه",2]]]],"122":[[0,0,[["بَدِيعُ","مبتدع أي مبتدئ  هو فعيل بمعنى مفعل لأنه من أبدع. وعن قطرب: بدعه بمعنى أبدعه، فيكون بمعنى فاعل أيضا. وفسر الإبداع بالاختراع  لا على مثال سبق، وضد الإبداع: الاحتذاء «7» .",2]]]],"123":[[0,3,[["وقال الذين لا يعلمون","هم مشركو العرب",1]]],[12,14,[["الذين من قبلهم","اليهود",1]]],[17,18,[["تشابهت قلوبهم","فى الكفر",1]]],[23,23,[["يُوقِنُونَ","الإيقان إفعال من اليقين، وهو علم ما يثلج به الصّدر.",2]]]],"124":[[9,9,[["الْجَحِيمِ","النار إذا شبّ وقودها.",2]]]],"125":[[8,8,[["أَهْواءَهُمْ","جمع هوى.",2],["مِلَّتَهُمْ","الملّة: الدّين، مشتقّ من أمللت لأنها تبنى على مسموع ومتلوّ.",2]]]],"126":[[3,5,[["يتلونه حق تلاوته","يعملون به حق عمله",1]]]],"129":[[0,4,[["وإذ ابتلى إبراهيم ربه بكلمات","وهى الفرق والمضمنة والاستنشاق وقص الشارب والسواك وتقليم الاظافر وحلق العانه ونتف الابط والاستطابه بالماء والختان",1]]],[5,5,[["فأتمهن","عمل بهن",1]]],[7,10,[["إِنِّي جاعِلُكَ لِلنَّاسِ إِماماً","أي تأتمّ بك الناس فيتّبعونك ويأخذون عنك، وبهذا سمّي الإمام إماما لأن الناس يؤمّون أفعاله، أي يقصدونها ويتّبعونها  جعله الله شجرة الأنبياء لأن الأنبياء بعده من ولده صلوات الله عليهم أجمعين وسلامه.",2]]],[13,13,[["ذُرِّيَّتِي","الذّرّيّة: أولاده وأولاد الأولاد. قال بعض النّحويين:ذرّيّة تقديرها فعليّة من الذّرّ لأن الله- عز وجل- أخرج الخلق من صلب آدم عليه السلام كالذّرّ وَأَشْهَدَهُمْ عَلى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قالُوا بَلى  . وقال غيره:أصل ذرّيّة: ذرّورة على وزن فعلولة  فلما كثر التّضعيف أبدلت الرّاء الأخيرة ياء فصارت ذرّوية ثم أدغمت الواو في الياء فصارت ذرّيّة. وقيل: ذرّيّة فعّولة من: ذرأ الله الخلق، فأبدلت الهمزة ياء كما أبدلت في نبيء  والذّرّية، مثلث الذال  وقيل: مشتقّ من المذرى  وهو الطّرف.",2]]],[14,17,[["قال لا ينال عهدي","يعنى الامامه",1]]]],"130":[[3,4,[["مَثابَةً لِلنَّاسِ","مرجعا لهم يثوبون إليه أي يرجعون إليه في حجّهم وعمرتهم كل عام. ويقال: ثاب جسم فلان، إذا رجع بعد النّحول  قال الزّجّاجي: سمّي بالمصدر كالمقامة. والمثابة اسم المكان. قال الأخفش: ودخول التاء  للمبالغة  . وقال ابن عبّاس: مَثابَةً أي من قصده تمنّى العود إليه  .وقيل: مَثابَةً من الثواب، أي يحجون فيثابون عليه.",2]]],[5,5,[["وأمنا","اى من احدث حدثا فى غيره ثم لجا اليه امن",1]]],[10,10,[["مُصَلًّى","قال مجاهد: مدّعى «7» . وقال غيره: موضع صلاة،فكأنه يريد الشّرعية لا اللغوية.",2]]],[11,13,[["عَهِدْنا إِلى إِبْراهِيمَ","أي أوصيناه وأمرناه  .",2]]],[19,19,[["الْعاكِفِينَ","المقيمين، ومنه الاعتكاف وهو الإقامة في المسجد على الصلاة والذّكر لله عز وجل.",2]]]],"131":[[19,20,[["ومن كفر","المعنى فسارزقه",1]]],[24,24,[["أَضْطَرُّهُ","الاضطرار: افتعال من الضّرورة وهو فعل ما لا يتهيأ له الامتناع منه.",2]]],[29,29,[["الْمَصِيرُ","المرجع.",2]]]],"132":[[3,3,[["القواعد","اساس البيت",1]]]],"133":[[6,6,[["أُمَّةً","الأمّة على ثمانية أوجه:- الجماعة، كقوله: أُمَّةً مِنَ النَّاسِ يَسْقُونَ  .- وأتباع الأنبياء عليهم السلام، كما تقول: نحن من أمّة محمد صلّى الله عليه وسلّم.- والجامع للخير المقتدى به، كقوله: إِنَّ إِبْراهِيمَ كانَ أُمَّةً قانِتاً لِلَّهِ  .- والدّين والملّة، كقوله: إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ  .- والحين والزمان كقوله: إِلى أُمَّةٍ مَعْدُودَةٍ  . وقوله: وَادَّكَرَ بَعْدَ أُمَّةٍ «7» أي بعد حين، ومن قرأ أمه «8» وأمه «9» أي نسيان.- والقامة، يقال: فلان من الأمّة أي القامة.- والمنفرد بدين لا يشركه فيه أحد، قال صلّى الله عليه وسلّم: «يبعث زيد بن عمرو بن نفيل أمّة وحده»  .- والأم، يقال: هذه أمّة زيد، أي أمّ زيد  .- وهو محتمل لأن يكون حقيقة في الجميع، وأن يكون حقيقة في أحدها، مجازا في الآخر الباقي.",2]]],[10,10,[["مَناسِكَنا","أي متعبّداتنا، واحدها منسك ومنسك. وأصل النّسك من الذّبح، يقال: نسكت: أي ذبحت. والنّسيكة: الذّبيحة المتقرّب بها إلى الله عزّ وجلّ، ثم اتّسعوا فيه حتى جعلوها موضع العبادة  والطاعة، ومنه قيل للعابد: ناسك.",2]]]],"134":[[10,10,[["الحكمة","السنه",1]]],[11,11,[["ويزكيهم","يطهرهم من الكفر",1]]],[14,14,[["الْعَزِيزُ","الغالب في نفسك.",2]]]],"135":[[3,4,[["ملة إبراهيم","دينه",1]]],[5,8,[["إلا من سفه نفسه","قال ابن قتيبه الا من سفهت نفسه",1]]],[10,10,[["اصْطَفَيْناهُ","اختار  وهو افتعل من الصّفو وهو الخالص من الكدر والشّوائب، أبدل من تائه طاء لمجاورة الصاد وكان ثلاثيّا لازما، يقال:صفا الشيء يصفو، وجاء الافتعال منه متعدّيا.",2]]],[12,12,[["الدُّنْيا","تأنيث أدنى، وهو القرب، سميت بذلك لدنوّها وسبقها الآخرة. وهي من الصّفات الغالبة التي تذكر بدون موصوفها غالبا. والمشهور ضم الدال وحكى ابن قتيبة وغيره كسرها. وفي حقيقة الدنيا قولان للمتكلّمين:أحدهما: ما على الأرض مع الجو والهواء. وأظهرهما: كل المخلوقات من الجواهر والأعراض الموجودة.",2]]],[15,15,[["والْآخِرَةِ","تأنيث آخر أيضا وهو صفة غالبة.",2]]],[17,17,[["الصالح","هو القائم بما عليه من حقوق الله تعالى وحقوق عباده.",2]]]],"136":[[6,8,[["أَسْلَمْتُ لِرَبِّ الْعالَمِينَ","أي سلم ضميري، ومنه اشتقاق المسلم  .",2]]]],"137":[[0,1,[["ووصى بها","اى بالمله",1]]]],"138":[[18,21,[["آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ","العرب تجعل العمّ أبا والخالة أمّا، ومنه قوله: وَرَفَعَ  أَبَوَيْهِ عَلَى الْعَرْشِ  يعني أباه وخالتهوكانت أمّه قد ماتت  .",2]]]],"139":[[0,6,[["تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَها ما كَسَبَتْ","أي جماعة قد مضت.",2]]]],"140":[[7,9,[["بل ملة إبراهيم","اى بل نتبع ملة ابراهيم فى حال حنيفيته والحنيف المائل الى العباده",1]]],[10,10,[["حَنِيفاً","الحنيف من كان على دين إبراهيم صلّى الله عليه وسلّم، ثم سمّي من كان يختتن ويحج البيت في الجاهلية حنيفا. والحنيف اليوم: المسلم. وقيل: إنما سمّي إبراهيم عليه السلام حنيفا لأنه حنف عما كان يعبده أبوه وقومه من الآلهة إلى عبادة الله عزّ وجلّ، أي عدل عن ذلك ومال. وأصل الحنف ميل من إبهامي القدمين كل واحدة على صاحبتها  ، وكما قيل: إن الحنيف في اللغة المائل. قيل: معناه فيها المستقيم، وقيل: إنه مشترك بينهما نحو الجون وعسعس  .",2]]]],"141":[[13,13,[["الْأَسْباطِ","في بني يعقوب كالقبائل في بني إسماعيل.واحدهم سبط، وهم اثنا عشر سبطا من اثني عشر ولدا ليعقوب. وإنما سمّي هؤلاء بالأسباط وهؤلاء بالقبائل ليفصل بين ولد إسماعيل وولد إسحاق  قال الكرماني:السّبط، أي بكسر السّين جمع ينتسبون إلى أب واحد.",2]]]],"142":[[2,5,[["بمثل ما آمنتم به","المثل صله",1]]],[13,13,[["شِقاقٍ","عداوة ومباينة  وقيل: مباينة واختلاف.",2]]]],"143":[[0,1,[["صبغة الله","اى دينه والصبغه مردوده الى المله وقال ابن قتيبه الصبغه الختان وكان النصارى يصبغون اولادهم فى ماء فقال الزموا صبغة الله لا صبغة النصارى",1]]],[9,9,[["عابِدُونَ","موحّدون، كذا جاء في التّفسير. وقال أصحاب اللغة: عابدون: خاضعون أذلّاء، من قولهم معبّد، أي مذلّل قد أثّر الناس فيه  .",2]]]],"144":[[1,1,[["أَتُحَاجُّونَنا","أتجادلوننا، وقيل: أتخاصموننا.",2]]],[13,13,[["مُخْلِصُونَ","الإخلاص لله جلّ وعز: أن يكون العبد يقصد بنيّته وعمله إلى خالقه ولا يجعل ذلك لغرض الدنيا ولا ليحسن عند مخلوق وللإخلاص تعاريف كثيرة مبيّنة في غير هذا الموضع.",2]]]]});